    // 1. Arabic Plurals for "You have 3 items in this order" using all 6 forms
    const count = 3;
    const itemStrings = {
      zero: 'لا توجد عناصر في هذا الطلب',
      one: 'لديك عنصر واحد في هذا الطلب',
      two: 'لديك عنصران في هذا الطلب',
      few: 'لديك {count} عناصر في هذا الطلب',
      many: 'لديك {count} عنصرًا في هذا الطلب',
      other: 'لديك {count} عنصر في هذا الطلب',
    };

    // UAE standard digit format: Western numerals
    const digitsFormatter = new Intl.NumberFormat('ar-AE-u-nu-latn');
    const pluralCategory = new Intl.PluralRules('ar').select(count);
    const formattedItemText = itemStrings[pluralCategory].replace(
      '{count}',
      digitsFormatter.format(count)
    );

    document.getElementById('items-count-text').textContent = formattedItemText;

    // 2. Exact Dates computation: 3 November 2026 (Gregorian & Hijri Umm al-Qura)
    // Dubai Timezone is UTC+4 ('Asia/Dubai')
    const dueDate = new Date('2026-11-03T00:00:00+04:00');

    // Gregorian in Arabic with Western digits
    const gregorianFmt = new Intl.DateTimeFormat('ar-AE-u-nu-latn', {
      timeZone: 'Asia/Dubai',
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
    document.getElementById('gregorian-date').textContent = gregorianFmt.format(dueDate);

    // Hijri Umm al-Qura calendar for UAE/Gulf
    try {
      const hijriFmt = new Intl.DateTimeFormat('ar-AE-u-ca-islamic-umalqura-nu-latn', {
        timeZone: 'Asia/Dubai',
        day: 'numeric',
        month: 'long',
        year: 'numeric'
      });
      document.getElementById('hijri-date').textContent = hijriFmt.format(dueDate) + ' هـ';
    } catch (e) {
      // Fallback if islamic-umalqura isn't supported in environment
      document.getElementById('hijri-date').textContent = '23 جمادى الأولى 1448 هـ';
    }

    // 3. Normalise typed numbers (convert Arabic/Persian numerals to Western digits)
    function toWesternDigits(str) {
      return str
        .replace(/[٠-٩]/g, d => d.charCodeAt(0) - 1632)
        .replace(/[۰-۹]/g, d => d.charCodeAt(0) - 1776);
    }

    const phoneInput = document.getElementById('phone-input');

    phoneInput.addEventListener('input', (e) => {
      // Normalise Arabic keyboards on the fly
      let raw = toWesternDigits(e.target.value);
      // Strip non-digits and leading zero if typed after prefix
      let cleaned = raw.replace(/\D/g, '');
      if (cleaned.startsWith('0')) {
        cleaned = cleaned.substring(1);
      }

      // Format as UAE local pattern: 50 123 4567
      let formatted = '';
      if (cleaned.length > 0) formatted += cleaned.substring(0, 2);
      if (cleaned.length > 2) formatted += ' ' + cleaned.substring(2, 5);
      if (cleaned.length > 5) formatted += ' ' + cleaned.substring(5, 9);

      e.target.value = formatted;
    });

    // 4. Pay Button Feedback
    const payBtn = document.getElementById('btn-pay');
    const toast = document.getElementById('toast');
    const toastText = document.getElementById('toast-text');

    payBtn.addEventListener('click', () => {
      const enteredPhone = phoneInput.value.replace(/\s+/g, '');

      if (enteredPhone.length < 9) {
        toastText.textContent = 'يرجى إدخال رقم هاتف متحرك صحيح لتلقي الإيصال';
